import 'package:flutter/material.dart';
import 'package:rastreo_embarques_app/pantallas/PaginaHistorial.dart';
import 'package:rastreo_embarques_app/pantallas/PaginaStatus.dart';

// Clase Envio para representar un registro de envío
class Envio {
  final String id;
  final String producto;
  final int cantidad;
  final String nombrePropietario;
  final String imagenUrl;

  Envio({
    required this.id,
    required this.producto,
    required this.cantidad,
    required this.nombrePropietario,
    required this.imagenUrl,
  });
}

class PaginaHome extends StatefulWidget {
  const PaginaHome({Key? key}) : super(key: key);

  @override
  _PaginaHomeState createState() => _PaginaHomeState();
}

class _PaginaHomeState extends State<PaginaHome> {
  int _paginaActual = 0; // Empezamos en la página Home

  final List<Widget> _paginas = [
    const PaginaHomeContent(),
    const PaginaStatus(),
    const PaginaHistorial(),
  ];

  // Títulos y colores del AppBar según la página activa
  final List<String> _titulos = ["Home", "Status", "Historial"];
  final List<Color> _coloresAppBar = [
    Colors.green, // Color para la página Home
    Colors.blue, // Color para la página Status
    Colors.orange, // Color para la página Historial
  ];

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title:
            Text(_titulos[_paginaActual]), // Título que cambia según la página
        backgroundColor:
            _coloresAppBar[_paginaActual], // Color que cambia según la página
      ),
      body: _paginas[_paginaActual], // Muestra la página según el índice
      bottomNavigationBar: BottomNavigationBar(
        onTap: (index) {
          setState(() {
            _paginaActual = index; // Cambiar el índice de la página
          });
        },
        currentIndex: _paginaActual, // Índice actual de la página
        items: const [
          BottomNavigationBarItem(icon: Icon(Icons.home), label: "Home"),
          BottomNavigationBarItem(
              icon: Icon(Icons.local_airport), label: "Status"),
          BottomNavigationBarItem(
              icon: Icon(Icons.history), label: "Historial"),
        ],
      ),
    );
  }
}

